import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadTamparaData(){const e=readFileSync(resolve(__dirname,"../../frontend/tampara-lake-explorer/tampara-data.js"),"utf-8");return new Function(e+"\nreturn { TAMPARA_INFO, ECOLOGY_HYDROLOGY, BIRD_FISH_SPECIES, MAP_HOTSPOTS, GALLERY_IMAGES };")()}function loadWetlandsLandingData(){let e=readFileSync(resolve(__dirname,"../../frontend/wetlands/wetlands-data.js"),"utf-8");e=e.replace(/export\s+const\s+/g,"const ");return new Function(e+"\nreturn WETLANDS_DATA;")()}describe("Tampara Lake Explorer — Data & Integration Tests",()=>{let e;beforeAll(()=>{e=loadTamparaData()}),describe("TAMPARA_INFO metadata",()=>{it("contains correct wetland metadata and status",()=>{expect(e.TAMPARA_INFO.id).toBe("tampara-lake"),expect(e.TAMPARA_INFO.name).toBe("Tampara Lake"),expect(e.TAMPARA_INFO.ramsarYear).toBe(2022),expect(e.TAMPARA_INFO.ramsarSiteNo).toBe(2488),expect(e.TAMPARA_INFO.state).toBe("Odisha")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.TAMPARA_INFO.quickStats)).toBe(!0),expect(e.TAMPARA_INFO.quickStats.length).toBe(6)})}),describe("ECOLOGY_HYDROLOGY",()=>{it("contains overview, hydrology, fisheries, and conservation status",()=>{expect(e.ECOLOGY_HYDROLOGY.overview).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.hydrology).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.fisheriesAndEconomy).toBeDefined(),expect(e.ECOLOGY_HYDROLOGY.conservationStatus).toBeDefined()})}),describe("BIRD_FISH_SPECIES catalog",()=>{it("is a non-empty array of species",()=>{expect(Array.isArray(e.BIRD_FISH_SPECIES)).toBe(!0),expect(e.BIRD_FISH_SPECIES.length).toBeGreaterThanOrEqual(4)}),it("includes Common Pochard and Rohu Fish",()=>{const t=e.BIRD_FISH_SPECIES.find(e=>"common-pochard"===e.id),a=e.BIRD_FISH_SPECIES.find(e=>"labeo-rohita"===e.id);expect(t).toBeDefined(),expect(a).toBeDefined()})}),describe("Landing Page Integration",()=>{it("is integrated in WETLANDS_DATA landing page dataset",()=>{const e=loadWetlandsLandingData().wetlands.find(e=>"tampara-lake"===e.id);expect(e).toBeDefined(),expect(e.exploreUrl).toBe("../tampara-lake-explorer/index.html")})})});